const mount=document.querySelector('#idea-editor');
if(mount){
const DB='ai-workflow-idea-deck',STORE='presentation',KEY='main',MAX_UNDO=80;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const defaults={version:4,locked:false,cover:{title:'THE MACHINE LEAVES A TRACE',subtitle:'A project proposal about making AI visible as a material process.',titleColor:'#10110d',subtitleColor:'#10110d',titleBold:true,subtitleBold:false,titleSize:126,subtitleSize:36},sections:[{id:uid(),layout:0,bg:'#cfff00',title:'THE WORKFLOW BECOMES THE SUBJECT',body:'Prompts, selections, errors, iterations and human intervention remain visible. The final work is not only an outcome—it is also a record of negotiation.',titleColor:'#10110d',bodyColor:'#10110d',titleBold:true,bodyBold:false,titleSize:64,bodySize:26,stageWidth:100,stageHeight:500,media:[],textBoxes:[]}]};
let state,saveTimer,drag,savedRange,activeRich,richRunning=false;const undoStack=[];
const openDB=()=>new Promise((resolve,reject)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});
async function load(){try{const db=await openDB();return await new Promise((resolve,reject)=>{const r=db.transaction(STORE).objectStore(STORE).get(KEY);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}catch{return null}}
async function persist(){try{const db=await openDB();await new Promise((resolve,reject)=>{const r=db.transaction(STORE,'readwrite').objectStore(STORE).put(state,KEY);r.onsuccess=resolve;r.onerror=()=>reject(r.error)});toast('SAVED IN THIS BROWSER')}catch{toast('COULD NOT SAVE')}}
const queueSave=()=>{clearTimeout(saveTimer);saveTimer=setTimeout(persist,260)};
const clone=v=>structuredClone(v);
function checkpoint(){undoStack.push(clone(state));if(undoStack.length>MAX_UNDO)undoStack.shift();updateUndo()}
function undo(){const previous=undoStack.pop();if(!previous){toast('NOTHING TO UNDO');return}state=previous;persist();render();toast('UNDONE')}
function updateUndo(){const b=mount.querySelector('[data-action="undo"]');if(b)b.disabled=!undoStack.length}
function clean(html){const t=document.createElement('template');t.innerHTML=html;const allowed=new Set(['B','STRONG','SPAN','BR','DIV','P','FONT']);[...t.content.querySelectorAll('*')].forEach(el=>{const color=el.style.color||el.getAttribute('color')||'',bg=el.style.backgroundColor||'',weight=el.style.fontWeight||'';[...el.attributes].forEach(a=>el.removeAttribute(a.name));if(!allowed.has(el.tagName)){el.replaceWith(...el.childNodes);return}let safe=el;if(el.tagName==='FONT'){safe=document.createElement('span');safe.innerHTML=el.innerHTML;el.replaceWith(safe)}if(color)safe.style.color=color;if(bg)safe.style.backgroundColor=bg;if(weight)safe.style.fontWeight=weight});return t.innerHTML}
function migrate(input){if(!input)return clone(defaults);const old=Number(input.version||1);input.version=4;input.cover||=clone(defaults.cover);if(old<2){input.cover.title=esc(input.cover.title);input.cover.subtitle=esc(input.cover.subtitle)}input.cover.titleSize||=126;input.cover.subtitleSize||=36;input.sections||=[];input.sections.forEach(s=>{if(old<2){s.title=esc(s.title);s.body=esc(s.body)}s.titleSize||=64;s.bodySize||=26;s.stageWidth=Number(s.stageWidth||100);s.stageHeight=Number(s.stageHeight||500);s.media||=[];s.textBoxes||=[];s.media.forEach(m=>m.rotate=Number(m.rotate||0));s.textBoxes.forEach(b=>b.rotate=Number(b.rotate||0))});return input}
const getSection=id=>state.sections.find(s=>s.id===id);
const getBox=(sid,bid)=>getSection(sid)?.textBoxes.find(b=>b.id===bid);
const textTools=(scope,key,color,bold,size)=>`<span class="text-tools"><label>SIZE <input type="range" min="14" max="180" step="1" data-action="font-size" data-scope="${scope}" data-key="${key}" value="${size}"><output>${size}px</output></label><label>COLOR <input type="color" data-action="color" data-scope="${scope}" data-key="${key}" value="${color}"></label><label><input type="checkbox" data-action="bold" data-scope="${scope}" data-key="${key}" ${bold?'checked':''}> BOLD</label></span>`;
const editable=(tag,cls,scope,key,html,color,bold,size)=>`<div class="editable-line">${textTools(scope,key,color,bold,size)}<${tag} class="${cls} rich-editable" data-edit="${key}" data-scope="${scope}" contenteditable="${state.locked?'false':'true'}" spellcheck="true" style="color:${color}!important;font-weight:${bold?'900':'400'};font-size:${size}px!important">${clean(html)}</${tag}></div>`;
const rotationControls=(kind,value)=>`<label class="rotation-control ${kind==='media'?'media-rotate':'text-box-rotate'}">ROTATE <input class="rotation-range" type="range" min="-180" max="180" step="1" value="${Math.max(-180,Math.min(180,value))}" data-action="rotate-${kind}"><input class="rotation-number" type="number" step="1" value="${value}" data-action="rotate-${kind}" aria-label="Rotation angle in degrees"><span>°</span></label>`;
const stageControls=s=>`<div class="stage-size-controls"><strong>CANVAS SIZE</strong><label>W <input type="range" min="50" max="150" step="1" value="${s.stageWidth}" data-action="stage-width"><input type="number" min="50" max="150" step="1" value="${s.stageWidth}" data-action="stage-width"><span>%</span></label><label>H <input type="range" min="280" max="1000" step="10" value="${s.stageHeight}" data-action="stage-height"><input type="number" min="280" max="1600" step="10" value="${s.stageHeight}" data-action="stage-height"><span>PX</span></label></div>`;
function mediaHTML(m,sid){const url=URL.createObjectURL(m.file);return `<article class="media-card ${m.kind}" data-media="${m.id}" data-section="${sid}" style="--x:${m.x}%;--y:${m.y}%;--w:${m.w}%;--z:${m.z};--rotate:${m.rotate}deg"><button class="media-grip" type="button" aria-label="Move media">DRAG / MOVE</button><button class="media-remove" type="button" aria-label="Remove media">×</button><div class="media-content">${m.kind==='image'?`<img src="${url}" alt="${esc(m.name)}">`:`<video src="${url}" playsinline preload="metadata" ${state.locked?'controls':''} aria-label="${esc(m.name)}"></video>`}</div>${rotationControls('media',m.rotate)}<button class="media-resize" type="button" aria-label="Resize media">↘</button></article>`}
const boxHTML=(b,sid)=>`<article class="free-text-box" data-box="${b.id}" data-section="${sid}" style="--x:${b.x}%;--y:${b.y}%;--w:${b.w}%;--z:${b.z};--rotate:${b.rotate}deg"><button class="text-box-grip" type="button" aria-label="Move text box">TEXT / MOVE</button><button class="text-box-remove" type="button" aria-label="Remove text box">×</button><div class="free-text-content rich-editable" data-box-edit="${b.id}" data-section="${sid}" contenteditable="${state.locked?'false':'true'}" spellcheck="true" style="font-size:${b.size}px!important">${clean(b.html)}</div><label class="text-box-size">SIZE <input type="range" min="14" max="120" step="1" value="${b.size}" data-action="box-size"><output>${b.size}px</output></label>${rotationControls('box',b.rotate)}<button class="text-box-resize" type="button" aria-label="Resize text box">↘</button></article>`;
function sectionHTML(s,i){return `<section class="deck-section layout-${s.layout}" data-section="${s.id}" style="--section-bg:${s.bg}"><div class="section-kicker"><span>PART ${String(i+1).padStart(2,'0')} / IDEA FRAME</span><div class="section-kicker-actions"><label class="section-bg-tool">BACKGROUND <input type="color" data-action="section-bg" value="${s.bg}"></label><button class="delete-section" type="button" data-delete-section="${s.id}">DELETE SECTION ×</button></div></div><div class="section-grid"><div class="section-copy">${editable('h2','section-title',s.id,'title',s.title,s.titleColor,s.titleBold,s.titleSize)}${editable('p','section-body',s.id,'body',s.body,s.bodyColor,s.bodyBold,s.bodySize)}</div><div class="media-stage-wrap">${stageControls(s)}<div class="media-stage" data-stage="${s.id}" style="width:${s.stageWidth}%;height:${s.stageHeight}px">${s.media.length||s.textBoxes.length?'':'<div class="media-empty">ADD IMAGES, VIDEOS OR TEXT BOXES<br>THEN DRAG + RESIZE</div>'}${s.media.map(m=>mediaHTML(m,s.id)).join('')}${s.textBoxes.map(b=>boxHTML(b,s.id)).join('')}<div class="media-toolbar"><label class="upload-media">+ ADD VISUALS<input type="file" accept="image/*,video/*" multiple data-upload="${s.id}"></label><button class="add-text-box" type="button" data-add-text="${s.id}">+ ADD TEXT BOX</button></div></div></div></div></section>`}
function render(){savedRange=null;activeRich=null;mount.innerHTML=`<div class="idea-shell ${state.locked?'locked':'editing'}"><div class="idea-editor-bar"><div class="editor-mode-copy"><strong>${state.locked?'PRESENTATION MODE':'EDIT MODE'}</strong><small>${state.locked?'Layout locked · hover images · click videos':'Select text for rich formatting · Ctrl+Z to undo'}</small></div><div class="selection-toolbar" aria-label="Selected text formatting"><span>SELECTED TEXT</span><button type="button" data-rich="bold"><b>B</b></button><label>TEXT <input type="color" value="#10110d" data-rich="foreColor"></label><label>HIGHLIGHT <input type="color" value="#cfff00" data-rich="hiliteColor"></label></div><div class="editor-actions"><button class="undo-button" type="button" data-action="undo" ${undoStack.length?'':'disabled'}>CTRL+Z / UNDO</button><button class="mode-button" type="button" data-action="toggle-lock" aria-pressed="${state.locked}">${state.locked?'EDIT PRESENTATION':'FINISH + LOCK'}</button></div></div><header class="deck-cover"><div class="cover-fields">${editable('h1','cover-title','cover','title',state.cover.title,state.cover.titleColor,state.cover.titleBold,state.cover.titleSize)}${editable('p','cover-subtitle','cover','subtitle',state.cover.subtitle,state.cover.subtitleColor,state.cover.subtitleBold,state.cover.subtitleSize)}</div></header><div class="deck-sections">${state.sections.map(sectionHTML).join('')}</div><div class="deck-add-zone"><button class="add-section" type="button" data-action="add-section">+ ADD NEXT SECTION</button></div></div><div class="idea-toast" role="status"></div>`;bind()}
function toast(message){const el=mount.querySelector('.idea-toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(el.hideTimer);el.hideTimer=setTimeout(()=>el.classList.remove('show'),1500)}
function updateRich(el){const html=clean(el.innerHTML);if(el.dataset.boxEdit)getBox(el.dataset.section,el.dataset.boxEdit).html=html;else{const target=el.dataset.scope==='cover'?state.cover:getSection(el.dataset.scope);target[el.dataset.edit]=html}queueSave()}
function syncAllEditors(){
mount.querySelectorAll('.rich-editable').forEach(el=>{const html=clean(el.innerHTML);if(el.dataset.boxEdit){const box=getBox(el.dataset.section,el.dataset.boxEdit);if(box)box.html=html}else{const target=el.dataset.scope==='cover'?state.cover:getSection(el.dataset.scope);if(target)target[el.dataset.edit]=html}});
mount.querySelectorAll('[data-action="font-size"]').forEach(input=>{const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);if(target)target[`${input.dataset.key}Size`]=Number(input.value)});
mount.querySelectorAll('[data-action="color"]').forEach(input=>{const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);if(target)target[`${input.dataset.key}Color`]=input.value});
mount.querySelectorAll('[data-action="bold"]').forEach(input=>{const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);if(target)target[`${input.dataset.key}Bold`]=input.checked});
mount.querySelectorAll('.deck-section').forEach(sectionEl=>{const section=getSection(sectionEl.dataset.section);if(!section)return;const bg=sectionEl.querySelector('[data-action="section-bg"]'),width=sectionEl.querySelector('[data-action="stage-width"][type="number"]'),height=sectionEl.querySelector('[data-action="stage-height"][type="number"]');if(bg)section.bg=bg.value;if(width)section.stageWidth=Number(width.value);if(height)section.stageHeight=Number(height.value)});
mount.querySelectorAll('.media-card').forEach(el=>{const item=itemFrom(el),number=el.querySelector('[data-action="rotate-media"][type="number"]');if(item&&number)item.rotate=Number(number.value)||0});
mount.querySelectorAll('.free-text-box').forEach(el=>{const box=getBox(el.dataset.section,el.dataset.box),size=el.querySelector('[data-action="box-size"]'),number=el.querySelector('[data-action="rotate-box"][type="number"]');if(!box)return;if(size)box.size=Number(size.value);if(number)box.rotate=Number(number.value)||0});
}
function restoreSelection(){if(!savedRange||!activeRich?.isConnected)return false;const sel=window.getSelection();sel.removeAllRanges();sel.addRange(savedRange);return true}
function applyRich(command,value=null){if(!restoreSelection()||savedRange.collapsed){toast('SELECT SOME TEXT FIRST');return}checkpoint();richRunning=true;activeRich.focus({preventScroll:true});restoreSelection();document.execCommand(command,false,value);updateRich(activeRich);richRunning=false;const sel=window.getSelection();savedRange=sel?.rangeCount?sel.getRangeAt(0).cloneRange():null;toast('TEXT FORMATTED')}
function bind(){
mount.querySelector('[data-action="toggle-lock"]').addEventListener('click',async()=>{syncAllEditors();checkpoint();state.locked=!state.locked;clearTimeout(saveTimer);await persist();render();window.scrollTo({top:document.querySelector('.idea-deck').offsetTop,behavior:'smooth'})});mount.querySelector('[data-action="undo"]').addEventListener('click',undo);
mount.querySelector('[data-action="add-section"]')?.addEventListener('click',()=>{checkpoint();const n=state.sections.length;state.sections.push({id:uid(),layout:Math.floor(Math.random()*3),bg:['#cfff00','#ff4a00','#fff7d6'][n%3],title:'NEW IDEA / NEW DIRECTION',body:'Click here to write the next part of your proposal.',titleColor:'#10110d',bodyColor:'#10110d',titleBold:true,bodyBold:false,titleSize:64,bodySize:26,stageWidth:100,stageHeight:500,media:[],textBoxes:[]});persist();render();setTimeout(()=>document.querySelector('.deck-section:last-of-type')?.scrollIntoView({behavior:'smooth'}),30)});
mount.querySelectorAll('[data-delete-section]').forEach(btn=>btn.addEventListener('click',()=>{syncAllEditors();checkpoint();state.sections=state.sections.filter(section=>section.id!==btn.dataset.deleteSection);persist();render();toast('SECTION DELETED · CTRL+Z TO RESTORE')}));
mount.querySelectorAll('.rich-editable[contenteditable="true"]').forEach(el=>{el.addEventListener('input',()=>{if(!richRunning)checkpoint();updateRich(el)});el.addEventListener('blur',()=>updateRich(el))});
mount.querySelectorAll('[data-action="font-size"]').forEach(input=>{input.addEventListener('pointerdown',checkpoint);input.addEventListener('input',()=>{const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);target[`${input.dataset.key}Size`]=Number(input.value);input.closest('.editable-line').querySelector('[data-edit]').style.fontSize=`${input.value}px`;input.nextElementSibling.value=`${input.value}px`;queueSave()})});
mount.querySelectorAll('[data-action="color"]').forEach(input=>{input.addEventListener('pointerdown',checkpoint);input.addEventListener('input',()=>{const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);target[`${input.dataset.key}Color`]=input.value;input.closest('.editable-line').querySelector('[data-edit]').style.color=input.value;queueSave()})});
mount.querySelectorAll('[data-action="bold"]').forEach(input=>input.addEventListener('change',()=>{checkpoint();const target=input.dataset.scope==='cover'?state.cover:getSection(input.dataset.scope);target[`${input.dataset.key}Bold`]=input.checked;input.closest('.editable-line').querySelector('[data-edit]').style.fontWeight=input.checked?'900':'400';queueSave()}));
mount.querySelectorAll('[data-action="section-bg"]').forEach(input=>{input.addEventListener('pointerdown',checkpoint);input.addEventListener('input',()=>{const sec=input.closest('.deck-section');getSection(sec.dataset.section).bg=input.value;sec.style.setProperty('--section-bg',input.value);queueSave()})});
mount.querySelectorAll('[data-rich]').forEach(control=>{if(control.tagName==='BUTTON'){control.addEventListener('mousedown',e=>e.preventDefault());control.addEventListener('click',()=>applyRich(control.dataset.rich))}else control.addEventListener('input',()=>applyRich(control.dataset.rich,control.value))});
mount.querySelectorAll('[data-upload]').forEach(input=>input.addEventListener('change',async()=>{checkpoint();const s=getSection(input.dataset.upload),base=s.media.length;for(const [i,file] of [...input.files].entries()){const kind=file.type.startsWith('video/')?'video':file.type.startsWith('image/')?'image':null;if(!kind)continue;s.media.push({id:uid(),kind,name:file.name,file,x:6+((base+i)*17)%48,y:8+((base+i)*19)%52,w:kind==='video'?52:38,z:base+i+2,rotate:0})}await persist();render()}));
mount.querySelectorAll('[data-add-text]').forEach(btn=>btn.addEventListener('click',()=>{checkpoint();const s=getSection(btn.dataset.addText),n=s.textBoxes.length;s.textBoxes.push({id:uid(),html:'TYPE SOMETHING',x:9+n*8,y:12+n*9,w:42,z:s.media.length+n+20,size:28,rotate:0});persist();render();setTimeout(()=>mount.querySelector(`[data-section="${s.id}"] [data-box-edit]:last-of-type`)?.focus(),20)}));
mount.querySelectorAll('.media-remove').forEach(btn=>btn.addEventListener('click',()=>{checkpoint();const card=btn.closest('.media-card'),s=getSection(card.dataset.section);s.media=s.media.filter(m=>m.id!==card.dataset.media);persist();render()}));
mount.querySelectorAll('.text-box-remove').forEach(btn=>btn.addEventListener('click',()=>{checkpoint();const el=btn.closest('.free-text-box'),s=getSection(el.dataset.section);s.textBoxes=s.textBoxes.filter(b=>b.id!==el.dataset.box);persist();render()}));
mount.querySelectorAll('.media-grip,.text-box-grip').forEach(h=>h.addEventListener('pointerdown',startMove));mount.querySelectorAll('.media-resize,.text-box-resize').forEach(h=>h.addEventListener('pointerdown',startResize));
mount.querySelectorAll('[data-action="rotate-media"],[data-action="rotate-box"]').forEach(input=>{input.addEventListener(input.type==='range'?'pointerdown':'focus',checkpoint);input.addEventListener('input',()=>{const visual=input.closest('.media-card,.free-text-box'),item=itemFrom(visual),value=Number(input.value);if(!Number.isFinite(value))return;item.rotate=Math.max(-9999,Math.min(9999,value));visual.style.setProperty('--rotate',`${item.rotate}deg`);const control=input.closest('.rotation-control');control.querySelector('.rotation-range').value=String(Math.max(-180,Math.min(180,item.rotate)));control.querySelector('.rotation-number').value=String(item.rotate);queueSave()})});
mount.querySelectorAll('[data-action="stage-width"],[data-action="stage-height"]').forEach(input=>{input.addEventListener(input.type==='range'?'pointerdown':'focus',checkpoint);input.addEventListener('input',()=>{const sectionElement=input.closest('.deck-section'),section=getSection(sectionElement.dataset.section),stage=sectionElement.querySelector('.media-stage'),isWidth=input.dataset.action==='stage-width',min=isWidth?50:280,max=isWidth?150:1600,value=Math.max(min,Math.min(max,Number(input.value)||min));if(isWidth){section.stageWidth=value;stage.style.width=`${value}%`}else{section.stageHeight=value;stage.style.height=`${value}px`}sectionElement.querySelectorAll(`[data-action="${input.dataset.action}"]`).forEach(control=>control.value=String(control.type==='range'?Math.min(Number(control.max),value):value));queueSave()})});
mount.querySelectorAll('[data-action="box-size"]').forEach(input=>{input.addEventListener('pointerdown',checkpoint);input.addEventListener('input',()=>{const el=input.closest('.free-text-box'),b=getBox(el.dataset.section,el.dataset.box);b.size=Number(input.value);el.querySelector('.free-text-content').style.fontSize=`${b.size}px`;input.nextElementSibling.value=`${b.size}px`;queueSave()})});
mount.querySelectorAll('.media-card.video video').forEach(video=>video.addEventListener('click',async()=>{if(!state.locked)return;try{await video.requestFullscreen();await video.play()}catch{toast('FULLSCREEN IS NOT AVAILABLE')}}));
}
function itemFrom(el){return el.classList.contains('media-card')?getSection(el.dataset.section).media.find(m=>m.id===el.dataset.media):getBox(el.dataset.section,el.dataset.box)}
function startMove(e){if(state.locked)return;e.preventDefault();checkpoint();const el=e.currentTarget.closest('.media-card,.free-text-box'),stage=el.parentElement,item=itemFrom(el),r=stage.getBoundingClientRect();drag={type:'move',pointer:e.pointerId,el,item,r,startX:e.clientX,startY:e.clientY,x:item.x,y:item.y};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.addEventListener('pointermove',onDrag);e.currentTarget.addEventListener('pointerup',endDrag,{once:true})}
function startResize(e){if(state.locked)return;e.preventDefault();checkpoint();const el=e.currentTarget.closest('.media-card,.free-text-box'),stage=el.parentElement,item=itemFrom(el),r=stage.getBoundingClientRect();drag={type:'resize',pointer:e.pointerId,el,item,r,startX:e.clientX,w:item.w};e.currentTarget.setPointerCapture(e.pointerId);e.currentTarget.addEventListener('pointermove',onDrag);e.currentTarget.addEventListener('pointerup',endDrag,{once:true})}
function onDrag(e){if(!drag||e.pointerId!==drag.pointer)return;if(drag.type==='move'){drag.item.x=Math.max(0,Math.min(92,drag.x+(e.clientX-drag.startX)/drag.r.width*100));drag.item.y=Math.max(0,Math.min(86,drag.y+(e.clientY-drag.startY)/drag.r.height*100));drag.el.style.setProperty('--x',`${drag.item.x}%`);drag.el.style.setProperty('--y',`${drag.item.y}%`)}else{drag.item.w=Math.max(20,Math.min(88,drag.w+(e.clientX-drag.startX)/drag.r.width*100));drag.el.style.setProperty('--w',`${drag.item.w}%`)}}
function endDrag(e){e.currentTarget.removeEventListener('pointermove',onDrag);drag=null;queueSave()}
document.addEventListener('selectionchange',()=>{if(state?.locked)return;const sel=window.getSelection();if(!sel?.rangeCount||sel.isCollapsed)return;const el=sel.anchorNode?.parentElement?.closest?.('.rich-editable');if(!el||!mount.contains(el))return;activeRich=el;savedRange=sel.getRangeAt(0).cloneRange()});
document.addEventListener('keydown',e=>{if(!mount.isConnected||!(e.ctrlKey||e.metaKey)||e.key.toLowerCase()!=='z'||e.shiftKey)return;e.preventDefault();undo()});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden'&&state){syncAllEditors();clearTimeout(saveTimer);persist()}});
window.addEventListener('pagehide',()=>{if(state){syncAllEditors();clearTimeout(saveTimer);persist()}});
state=migrate(await load());render();
}
